parameters.text:
=Create one program-specific visual asset concept for this education program, then prepare a precise image-generation prompt. Use the selected asset category, full program data, brand data, and buyer personas to make the image useful for a program landing page and enrollment marketing.

Selected asset category: {{ $json.body.assetCategory }}
Selected category label: {{ $json.body.assetCategoryLabel }}
Program id: {{ $json.body.programId }}
Program name: {{ $json.body.programName }}

Available program asset categories JSON:
{{ JSON.stringify($json.body.availableAssetCategories || [], null, 2) }}

Program asset taxonomy:
{
  "programAssets": {
    "heroImages": [],
    "lifestyleImages": [],
    "handsOnTrainingImages": [],
    "classroomImages": [],
    "facultyImages": [],
    "careerImages": [],
    "testimonialImages": [],
    "galleryImages": [],
    "videos": [],
    "documents": []
  }
}

Brand JSON:
{{ JSON.stringify($json.body.brand, null, 2) }}

Program JSON:
{{ JSON.stringify($json.body.program || {}, null, 2) }}

Buyer personas JSON:
{{ JSON.stringify($json.body.buyerPersonRecords || [], null, 2) }}

Current draft JSON:
{{ JSON.stringify($json.body.currentDraft || {}, null, 2) }}

Return only valid JSON. Do not use markdown. Do not wrap the response in an array. The JSON must match this shape:
{
  "visualAsset": {
    "name": "",
    "assetType": "Image",
    "assetCategory": "{{ $json.body.assetCategory }}",
    "url": "",
    "notes": ""
  },
  "imagePrompt": ""
}

Image prompt rules:
- Generate a photorealistic marketing image for this specific education program.
- Do not include readable text, logos, watermarks, UI, brand marks, or fictional seal designs inside the image.
- Avoid depicting real identifiable public figures or celebrities.
- Respect the brand context, colors, location, audience, selected program, program benefits, career outcomes, delivery mode, duration, campus context, and buyer personas.
- Make the image premium, modern, realistic, inclusive, and enrollment-oriented.
- If the category is heroImages, create a strong above-the-fold visual for the program landing page.
- If the category is handsOnTrainingImages, classroomImages, or galleryImages, show relevant training, labs, class environments, or program-specific learning moments.
- If the category is facultyImages, show credible mentors or instructors aligned with the program context.
- If the category is careerImages, show students or graduates in professional contexts directly aligned with this specific program. For healthcare programs, show appropriate clinical or administrative environments.
- If the category is testimonialImages, create a natural portrait aligned with one of the buyer personas and the selected program.
- If the category is videos or documents, still return an image-style visual asset concept that can be used as a cover, thumbnail, or document hero.
- Use concise notes explaining recommended use cases for this program landing page, ads, email, retargeting, or social.

parameters.jsCode:
const raw = $json.output ?? $json.text ?? $json.response ?? $json.message ?? $json;
const request = $('Webhook - edwin-program-assets-agent').item.json.body || {};

function parseJsonCandidate(value) {
  if (typeof value === 'object' && value !== null) return value;
  if (typeof value !== 'string') return null;

  const cleaned = value
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch {
      return null;
    }
  }
}

const parsed = parseJsonCandidate(raw);
const visualAsset = parsed?.visualAsset || parsed?.asset || parsed;
const imagePrompt = parsed?.imagePrompt || parsed?.prompt || '';

if (!visualAsset || !visualAsset.name || !imagePrompt) {
  return {
    json: {
      ok: false,
      agent: 'edwin-program-assets-agent',
      message: 'No se pudo generar un visual asset valido',
      rawOutput: raw
    }
  };
}

visualAsset.assetType = visualAsset.assetType || 'Image';
visualAsset.assetCategory = visualAsset.assetCategory || request.assetCategory || 'lifestyleImages';
visualAsset.url = visualAsset.url || '';
visualAsset.notes = visualAsset.notes || '';

return {
  json: {
    ok: true,
    agent: 'edwin-program-assets-agent',
    message: 'program asset generado, generando imagen',
    visualAsset,
    imagePrompt,
    rawOutput: raw
  }
};

const uploadResponse = $json;
const previous = $('Normalize Program Visual Asset JSON').item.json;
const visualAsset = previous.visualAsset;
const uploadedUrl = uploadResponse.url || uploadResponse.data?.url || uploadResponse.fileUrl || '';

visualAsset.url = uploadedUrl || visualAsset.url || '';

return {
  json: {
    ok: Boolean(visualAsset.url),
    agent: 'edwin-program-assets-agent',
    message: visualAsset.url ? 'program asset generado correctamente' : 'No se recibio URL de imagen del nodo upload',
    visualAsset,
    imageUrl: visualAsset.url,
    imagePrompt: previous.imagePrompt,
    imageGenerated: Boolean(visualAsset.url),
    upload: uploadResponse
  }
};
